<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Leave request · Luvep</title><style>body{font:14px/1.6 Arial,sans-serif;color:#243128;max-width:850px;margin:40px auto;padding:0 24px}header{border-bottom:3px solid #36582e;padding-bottom:20px}img{width:110px}h1{font-size:28px}h2{font-size:20px;margin-top:30px}dl{display:grid;grid-template-columns:160px 1fr;gap:10px}dt{font-weight:bold}dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}p{white-space:pre-wrap}button{background:#36582e;color:white;border:0;padding:12px 18px;border-radius:5px}@media print{button{display:none}body{margin:0;padding:0}@page{margin:18mm}}</style></head><body><header><img src="/images/luvep-hr-logo.png" alt="Luv, eP."><h1>Application for leave</h1><p>{{ $employee->user->name }} · {{ $employee->employee_number ?: 'Employee record' }}</p><button onclick="window.print()">Print / Save as PDF</button></header><h2>Request details</h2><dl><dt>Department / position</dt><dd>{{ $employee->department ?: '—' }} / {{ $employee->position ?: '—' }}</dd><dt>Leave type</dt><dd>{{ $leave->type }}{{ $leave->other_specify ? ' · '.$leave->other_specify : '' }}</dd><dt>Period</dt><dd>{{ $leave->start_date->toDateString() }} – {{ $leave->end_date->toDateString() }}</dd><dt>Working days</dt><dd>{{ $leave->total_days ?? 'Historical record' }} · {{ $leave->half_day ?: 'Full day' }}</dd><dt>Return date</dt><dd>{{ $leave->return_date?->toDateString() ?? 'Not recorded' }}</dd><dt>Reason</dt><dd>{{ $leave->reason ?: 'Not provided' }}</dd><dt>Cover / handover</dt><dd>{{ $leave->cover_person ?: '—' }} / {{ $leave->handover ?: '—' }}</dd><dt>Employee declaration</dt><dd>{{ $leave->declared_name ?: 'Historical record' }} · {{ $leave->employee_signed_at ?? 'No digital declaration recorded' }}</dd></dl><h2>Department Head decision</h2><dl><dt>Status</dt><dd>{{ $leave->decision ?: ucfirst($leave->status) }}</dd><dt>Comments</dt><dd>{{ $leave->manager_comments ?: 'Not recorded' }}</dd><dt>Reviewed</dt><dd>{{ $leave->reviewed_at ?? 'Awaiting decision' }}</dd></dl><footer><p>Luv, eP. · Private employee record · Generated {{ now('UTC')->format('Y-m-d H:i') }} UTC</p></footer></body></html>